export type SourceType = "currículo" | "libro" | "curso" | "videos" | "repositorio" | "documentación"

export type ProgrammingSourceV50 = {
  id: string
  title: string
  author: string
  type: SourceType
  url: string
  note: string
  license: string
}

export type ConceptV50 = {
  id: string
  title: string
  what: string
  why: string
  when: string
  whenNot: string
  mentalModel: string
  how: string[]
  terms: { term: string; meaning: string }[]
  exampleLanguage: "python" | "javascript" | "text"
  example: string
  breakdown: string[]
  guidedTask: string[]
  soloTask: string
  mistakes: string[]
  debug: string[]
  check: { q: string; a: string }[]
  mastery: string
}

export type GuidedLevelV50 = {
  code: string
  title: string
  phase: string
  orientation: string
  prerequisites: string[]
  outcomes: string[]
  concepts: ConceptV50[]
  project: string
  gate: string
  sources: string[]
}

