const C = (
  id: string,
  title: string,
  what: string,
  why: string,
  when: string,
  mentalModel: string,
  exampleLanguage: "python" | "javascript" | "text",
  example: string,
  breakdown: string[],
  mastery: string,
  terms: { term: string; meaning: string }[] = [],
  whenNot = "No lo uses por costumbre: primero confirma que el problema realmente necesita este concepto.",
): ConceptV50 => ({
  id,
  title,
  what,
  why,
  when,
  whenNot,
  mentalModel,
  how: [
    `1. Identifica qué problema resuelve ${title.toLowerCase()}.`,
    "2. Escribe un ejemplo pequeño con entrada y salida concretas.",
    "3. Predice el resultado antes de ejecutar.",
    "4. Ejecuta y compara el resultado real con tu predicción.",
    "5. Cambia una sola cosa y vuelve a observar qué efecto produce.",
    "6. Explica con tus propias palabras por qué funcionó.",
  ],
  terms,
  exampleLanguage,
  example,
  breakdown,
  guidedTask: [
    "Lee el ejemplo sin ejecutarlo y predice la salida.",
    "Señala qué parte representa datos, qué parte representa una decisión/operación y qué parte produce un resultado.",
    "Ejecuta el ejemplo.",
    "Modifica un valor y vuelve a predecir antes de ejecutar.",
    "Describe qué cambió y cuál fue la causa exacta.",
  ],
  soloTask: `Crea un ejemplo nuevo de ${title.toLowerCase()} sin copiar el ejemplo anterior. Debe tener al menos un caso normal y un caso límite.`,
  mistakes: [
    "Memorizar sintaxis sin comprender qué estado o dato está cambiando.",
    "Cambiar muchas líneas a la vez y luego no saber cuál cambio produjo el resultado.",
    "Dar por correcto un programa porque funciona con un solo ejemplo.",
  ],
  debug: [
    "Reproduce el fallo con el caso más pequeño posible.",
    "Compara estado esperado y estado real en cada paso.",
    "Localiza la primera línea donde ambos divergen.",
    "Corrige una sola causa, vuelve a ejecutar y agrega un test que evite la regresión.",
  ],
  check: [
    { q: `¿Qué problema resuelve ${title}?`, a: why },
    { q: `¿Cuándo usarías ${title}?`, a: when },
    { q: "¿Cómo comprobarías que tu solución es correcta?", a: "Con predicción, casos normales, casos límite, ejecución y una explicación de por qué el resultado satisface el objetivo." },
  ],
  mastery,
})

