export const guidedProgrammingLevelsV50: GuidedLevelV50[] = levelSpecs.map(([code,title,phase,orientation,prerequisites,outcomes,conceptIds,project,gate,sources]) => ({
  code,
  title,
  phase,
  orientation,
  prerequisites: [...prerequisites],
  outcomes: [...outcomes],
  concepts: [...conceptIds].map((id) => concepts[id]).filter(Boolean),
  project,
  gate,
  sources: [...sources],
}))

export const getGuidedLevelV50 = (code: string) => guidedProgrammingLevelsV50.find((level) => level.code === code) ?? guidedProgrammingLevelsV50[0]
export const getSourceV50 = (id: string) => programmingSourcesV50.find((source) => source.id === id)
